import re
from auto_config.generator.gnb.managed_objects.managed_object import ManagedObject


class EthifParamsGenerator(ManagedObject):

    def _prepare_section_content(self, execution_config, *args, **kwargs):

        self.set_linkSelectorDN()
        if not self.is_mo_ecpri and self.mo_num == '1':
            self.set_parameter('sbsTotal', self.enb_ent_config.get('sbs_total', 2000000))
            self.set_parameter('shapingOverhead', "Ethernet frame")
            self.set_parameter('sirTotal', 25000000)

    def set_linkSelectorDN(self):
        mrbts_id = self.enb_ent_config['id']
        mo_num = self.mo_num
        srch = re.search(r"TNL-(\d+)", self.dist_name)
        tnl_id = srch.group(1)
        if self.is_mo_ecpri:
            self.set_parameter('linkSelectorDN', f"MRBTS-{mrbts_id}/TNLSVC-1/TNL-{tnl_id}/ETHSVC-1/ETHLK-{mo_num}")
        elif self.mo_num == '1':
            self.set_parameter('linkSelectorDN', f"MRBTS-{mrbts_id}/TNLSVC-1/TNL-{tnl_id}/ETHSVC-1/L2SWI-1/IBRGPRT-1")
        elif self.mo_num == '2':
            self.set_parameter('linkSelectorDN', f"MRBTS-{mrbts_id}/TNLSVC-1/TNL-{tnl_id}/ETHSVC-1/L2SWI-1/BRGPRT-1")
